//! THE ONE READER'S CONFORMITY GUARD (`DECISIONS.md#namespaces-over-the-system-port`,
//! migration step 1).
//!
//! The source reader is generated by kin into the three runtimes
//! (`kin/readcore.kin` .. `kin/formsenc.kin`), and the host reads with it rather
//! than the compiler. What makes that safe is that its BYTES are today's: the
//! guest's own `flint.reader` + `flint.forms/encode`, run inside the embedded
//! compiler through its `preread` mode, are the reference, and every file in
//! `lib/`, `src/`, `corpus/` and the test fixtures is read both ways under three
//! option sets -- deferred (`:features :any`, what the stdlib is embedded as),
//! eager under the default features, and eager under `:optimize [perf]`'s.
//! Every file must come out byte-identical, and a file that does not read must
//! fail with the same message.
//!
//! The JVM and CLR copies are held to the same bytes by `bin/check-reader`,
//! which runs this with `FLINT_READER_REF_DIR` set: the reference bytes and a
//! manifest are written there, and each port's runner reads them back.
//!
//! `FLINT_READER_ONLY=<substring>` narrows the sweep to matching paths, and
//! `FLINT_READER_SHOW=1` prints the message of every read that failed alike.

use crate::load_compiler;
use flint_rt::codec::{parse, Val, Wire};
use std::path::{Path, PathBuf};

/// The three option sets, as the feature list a spec carries (none: deferred).
pub(crate) const MODES: &[(&str, Option<&[&str]>)] = &[
    ("deferred", None),
    ("default", Some(&["flint", "flint/check", "flint/nested"])),
    ("perf", Some(&["flint", "flint/nested"])),
];

fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap().to_path_buf()
}

/// Every source the sweep reads, as `(name, text)`: the name is what the read
/// is told its file is -- relative to `lib/` for the standard library, as the
/// build's own pre-read names it, and to the repository otherwise.
pub(crate) fn sources() -> Vec<(String, String)> {
    fn walk(dir: &Path, rel: &str, all_ext: bool, out: &mut Vec<(String, String)>) {
        let Ok(rd) = std::fs::read_dir(dir) else { return };
        let mut names: Vec<_> = rd.filter_map(|e| e.ok()).collect();
        names.sort_by_key(|e| e.path());
        for e in names {
            let p = e.path();
            let name = p.file_name().unwrap().to_string_lossy().to_string();
            let r = if rel.is_empty() { name.clone() } else { format!("{rel}/{name}") };
            if p.is_dir() {
                walk(&p, &r, all_ext, out);
            } else if r.ends_with(".cljc") || r.ends_with(".fln") || (all_ext && r.ends_with(".clj")) {
                if let Ok(t) = std::fs::read_to_string(&p) {
                    out.push((r, t));
                }
            }
        }
    }
    let root = root();
    let mut out = Vec::new();
    walk(&root.join("lib"), "", true, &mut out);
    walk(&root.join("src"), "src", true, &mut out);
    walk(&root.join("corpus"), "corpus", true, &mut out);
    // Fixtures only: the `.clj` files directly under `test/` are babashka
    // scripts, not flint sources.
    walk(&root.join("test"), "test", false, &mut out);
    if let Ok(only) = std::env::var("FLINT_READER_ONLY") {
        out.retain(|(n, _)| n.contains(&only));
    }
    out
}

/// The guest's bytes for every file under one mode: `Ok(bytes)` or
/// `Err(message)`.
fn reference(files: &[(String, String)], features: Option<&[&str]>) -> Vec<Result<Vec<u8>, String>> {
    let mut p = load_compiler().expect("the embedded compiler");
    let fmap = Val::Map(files.iter().map(|(k, v)| (Val::Str(k.clone()), Val::Str(v.clone()))).collect());
    let spec = match features {
        None => "{:files {} :guard true}".to_string(),
        Some(fs) => format!(
            "{{:files {{}} :guard true :features [{}]}}",
            fs.iter().map(|f| format!(":{f}")).collect::<Vec<_>>().join(" ")
        ),
    };
    let call = Val::Vector(vec![
        Val::Str("flint.selfhost/main".into()),
        Val::Vector(vec![Val::Str("split".into()), fmap, Val::Str("preread".into()), Val::Str(spec)]),
    ]);
    let mut w = Wire::new();
    call.write(&mut w);
    let bytes = p.call(&w.done()).unwrap_or_else(|e| panic!("the guest's pre-read failed: {e}"));
    let Val::Map(read) = parse(&bytes).unwrap() else { panic!("the pre-read answered something that is not a map") };
    files
        .iter()
        .map(|(name, _)| {
            match read.iter().find(|(k, _)| *k == Val::Str(name.clone())).map(|(_, v)| v) {
                Some(Val::Bytes(b)) => Ok(b.clone()),
                Some(Val::Map(m)) => Err(m
                    .iter()
                    .find(|(k, _)| *k == Val::Keyword(None, "error".into()))
                    .map(|(_, v)| match v {
                        Val::Str(s) => s.clone(),
                        other => format!("{other:?}"),
                    })
                    .unwrap_or_default()),
                other => panic!("the pre-read answered {other:?} for {name}"),
            }
        })
        .collect()
}

/// The kin reader's bytes for one file -- through `crate::read`, the door the
/// native CLI reads a project with, so this guards the code that ships.
pub(crate) fn kin_read(name: &str, text: &str, features: Option<&[&str]>) -> Result<Vec<u8>, String> {
    let fs: Option<Vec<String>> = features.map(|f| f.iter().map(|x| format!(":{x}")).collect());
    let how = crate::read::ReadAs { features: fs.as_deref(), tags: &[], portable: !name.ends_with(".fln") };
    crate::read::read_forms(name, text, &how)
}

#[test]
fn kin_reader_bytes_match_the_guest_reader() {
    let files = sources();
    assert!(files.len() > 100 || std::env::var("FLINT_READER_ONLY").is_ok(),
            "the sweep found only {} files", files.len());
    let out_dir = std::env::var("FLINT_READER_REF_DIR").ok().map(PathBuf::from);
    let mut manifest = String::new();
    let mut fails: Vec<String> = Vec::new();
    let mut compared = 0;
    let mut errors_alike = 0;
    for (mode, features) in MODES {
        let refs = reference(&files, *features);
        for (i, ((name, text), want)) in files.iter().zip(refs.iter()).enumerate() {
            let got = kin_read(name, text, *features);
            compared += 1;
            match (want, &got) {
                (Ok(a), Ok(b)) if a == b => {}
                (Err(a), Err(b)) if a == b => {
                    errors_alike += 1;
                    if std::env::var("FLINT_READER_SHOW").is_ok() {
                        println!("  alike {mode} {name}: {a}");
                    }
                }
                (Ok(a), Ok(b)) => {
                    let at = a.iter().zip(b.iter()).position(|(x, y)| x != y).unwrap_or(a.len().min(b.len()));
                    fails.push(format!("{mode} {name}: bytes differ at {at} ({} against {} bytes)", a.len(), b.len()));
                }
                (a, b) => fails.push(format!("{mode} {name}: guest {:?} kin {:?}",
                                              a.as_ref().map(|v| v.len()), b.as_ref().map(|v| v.len()))),

            }
            if let Some(dir) = &out_dir {
                let tag = format!("{mode}-{i}");
                std::fs::create_dir_all(dir).unwrap();
                std::fs::write(dir.join(format!("{tag}.src")), text).unwrap();
                match want {
                    Ok(b) => {
                        std::fs::write(dir.join(format!("{tag}.forms")), b).unwrap();
                    }
                    Err(m) => {
                        std::fs::write(dir.join(format!("{tag}.err")), m).unwrap();
                    }
                }
                manifest.push_str(&format!("{tag}\t{mode}\t{name}\n"));
            }
        }
    }
    if let Some(dir) = &out_dir {
        std::fs::write(dir.join("manifest.tsv"), &manifest).unwrap();
    }
    println!("kin reader: {compared} reads compared ({} files x {} modes), {errors_alike} failed alike, {} differ",
             files.len(), MODES.len(), fails.len());
    for f in fails.iter().take(40) {
        println!("  DIFF {f}");
    }
    assert!(fails.is_empty(), "{} of {compared} reads differ from the guest's", fails.len());
}
